#!/usr/bin/env node
/* Reconstruct V1.7 root and legacy 4 child KiCad sources from immutable V1.6.
 * The NEW protection schematic and THT_V17 library are standalone original native
 * CAD source, not copied from V1.6 and not regenerated by this script.
 * --check verifies byte-for-byte source-derived schematics. NO FAB / NO TX.
 */
"use strict";
const fs=require("fs"),path=require("path"),assert=require("assert");
const repo=path.resolve(__dirname,"../.."),dir=__dirname;
const OLD="PLL_RX_HIERARCHICAL_MASTER_V1.6",NAME="PLL_RX_HIERARCHICAL_MASTER_V1.7";
const read=p=>fs.readFileSync(path.join(repo,p),"utf8");
const pOld=n=>"04_KiCad/V1.6/"+n+"_V1.6.kicad_sch";
const wire=(a,b,c,d,n)=>'(wire (pts (xy '+a+' '+b+') (xy '+c+' '+d+')) (stroke (width 0) (type default)) (uuid "9e17bcd1-faae-4e37-bf17-000000000'+n+'"))';
let root=read(pOld("PLL_RX_HIERARCHICAL_MASTER"));
root=root.replaceAll('(project "'+OLD+'"','(project "'+NAME+'"');
for(const n of ["PLL_CORE_DIGITAL","PD_FILTER_DRIVER","VCO_RX_AND_LOBUF","POWER5_DISTRIBUTION"]){
 root=root.replace('"'+n+'_V1.6.kicad_sch"','"'+n+'_V1.7.kicad_sch"');
}
const k=root.indexOf('(property "Sheetname" "PWR_5V_RAILS"');
assert(k>=0);
const i=root.indexOf("(instances ",k);
const pin='(pin "+13V8_PROTECTED" passive (at 177.8 228.6 180) (uuid "9e17bcd1-faae-4e37-bf17-000000000201") (effects (font (size 1.27 1.27)) (justify left)))\n';
root=root.slice(0,i)+pin+root.slice(i);
const needle=/\(wire \(pts \(xy 154\.94 165\.1\) \(xy 154\.94 264\.16\)\)[^\n]*/g;
assert.strictEqual((root.match(needle)||[]).length,1);
root=root.replace(needle,wire(154.94,165.1,154.94,254,"202")+'\n'+wire(154.94,254,154.94,264.16,"203"));
root=root.replace("V1.6 FIVE SHEETS","V1.7 SIX SHEETS");
const extra=[
wire(129.54,228.6,177.8,228.6,"204"),
wire(129.54,254,154.94,254,"205"),
'(junction (at 154.94 254) (diameter 0) (color 0 0 0 0) (uuid "9e17bcd1-faae-4e37-bf17-000000000206"))',
'(sheet (at 43.18 208.28) (size 86.36 71.12) (stroke (width 0.1524) (type solid)) (fill (color 0 0 0 0.0000)) (uuid "9e17bcd1-faae-4e37-bf17-000000000006")',
' (property "Sheetname" "FUSED_13V8_INPUT" (at 43.18 207.01 0) (effects (font (size 1.27 1.27)) (justify left bottom)))',
' (property "Sheetfile" "INPUT_FUSE_REVERSE_TVS_V1.7.kicad_sch" (at 43.18 280.67 0) (effects (font (size 1.27 1.27)) (justify left top)))',
' (pin "+13V8_PROTECTED" passive (at 129.54 228.6 0) (uuid "9e17bcd1-faae-4e37-bf17-000000000207") (effects (font (size 1.27 1.27)) (justify right)))',
' (pin "GND" passive (at 129.54 254 0) (uuid "9e17bcd1-faae-4e37-bf17-000000000208") (effects (font (size 1.27 1.27)) (justify right)))',
' (instances (project "'+NAME+'" (path "/7b14bcd1-faae-4e37-bf14-000000000001" (page "6")))))'
];
root=root.trim().slice(0,-1)+'\n'+extra.join("\n")+'\n)\n';
function topFields(t){
 t=t.trim();assert(t.startsWith("(kicad_sch")&&t.endsWith(")"));
 t=t.slice("(kicad_sch".length,-1);
 const a=[];let depth=0,q=false,esc=false,at=0;
 for(let i=0;i<t.length;i++){
  const c=t[i];if(q){if(esc)esc=false;else if(c==="\\")esc=true;else if(c==='"')q=false;continue;}
  if(c==='"'){q=true;continue;}
  if(c==="("){if(!depth)at=i;depth++;}
  if(c===")"){depth--;if(depth<0)throw Error("Extra )");if(!depth)a.push(t.slice(at,i+1));}
 }
 assert(!depth&&!q);
 return a;
}
let foundH=0,removed=0;
let chunks=topFields(read(pOld("POWER5_DISTRIBUTION"))).map(x=>{
 if(x.startsWith('(label "+13V8_PROTECTED"') && x.includes("(at 111.76 71.12")){
  foundH++;return x.replace('(label "+13V8_PROTECTED"','(hierarchical_label "+13V8_PROTECTED" (shape passive)');
 }
 return x;
}).filter(x=>{
 if(x.startsWith("(symbol ")&&(x.includes('(property "Reference" "J601"')||x.includes('(property "Reference" "PWR601"'))){removed++;return false;}
 if(x.startsWith("(wire ")){
  const candidates=[
    ["(xy 45.72 71.12)","(xy 40.64 71.12)"],
    ["(xy 45.72 76.2)","(xy 40.64 76.2)"],
    ["(xy 53.34 157.48)","(xy 48.26 157.48)"]
  ];
  if(candidates.some(z=>x.includes(z[0])&&x.includes(z[1]))){removed++;return false;}
 }
 if(x.startsWith("(label ")){
  const coords=["(at 40.64 71.12 0)","(at 40.64 76.2 0)","(at 48.26 157.48 0)"];
  if(coords.some(z=>x.includes(z))){removed++;return false;}
 }
 return true;
});
assert.strictEqual(removed,8);assert.strictEqual(foundH,1);
const power="(kicad_sch\n"+chunks.map(x=>x.replaceAll('(project "'+OLD+'"','(project "'+NAME+'"').replace("IN MASTER V1.6 WITH UNQUALIFIED INPUT.","FROM V1.7 F701+D701; NO CONTINUOUS OVP.")).join("\n")+"\n)\n";
const outputs={
"PLL_RX_HIERARCHICAL_MASTER_V1.7.kicad_sch":root,
"POWER5_DISTRIBUTION_V1.7.kicad_sch":power
};
for(const name of ["PLL_CORE_DIGITAL","PD_FILTER_DRIVER","VCO_RX_AND_LOBUF"]){
 outputs[name+"_V1.7.kicad_sch"]=read(pOld(name)).replaceAll('(project "'+OLD+'"','(project "'+NAME+'"');
}
for(const [file,text] of Object.entries(outputs)){
 const dest=path.join(dir,file);
 if(process.argv.includes("--check")){
  assert.strictEqual(fs.readFileSync(dest,"utf8"),text,"Nonreproducible native KiCad file "+file);
 }else if(process.argv.includes("--write")){
  fs.writeFileSync(dest,text,"utf8");
 }else throw Error("Use --check or --write explicitly");
}
console.log(JSON.stringify({status:"PASS_V17_REPRODUCIBLE_SOURCE_DERIVED_NATIVE_SCHEMATICS",
  files:Object.keys(outputs).length,removed_external_direct_bypass:"J601",fab_authorized:false,tx_authorized:false}));
